{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useTableSelection",
    "subComponentOf": "Table",
    "displayName": "useTableSelection",
    "description": "Hook that returns a TablePlugin implementing row selection with checkboxes, select-all, and aria-selected. Uses React Context for independent checkbox re-renders.",
    "props": [
      {
        "name": "getIsItemSelected",
        "type": "(item: T) => boolean",
        "description": "Returns whether the given item is currently selected.",
        "required": true
      },
      {
        "name": "onSelectItem",
        "type": "(event: {item: T; isSelected: boolean}) => void",
        "description": "Called when a row checkbox is toggled. isSelected is the new desired state.",
        "required": true
      },
      {
        "name": "onSelectAll",
        "type": "(event: {isAllSelected: boolean}) => void",
        "description": "Called when the select-all header checkbox is toggled.",
        "required": true
      },
      {
        "name": "getIsAllSelected",
        "type": "() => boolean",
        "description": "Returns whether all selectable items are currently selected.",
        "required": true
      },
      {
        "name": "getIsIndeterminate",
        "type": "() => boolean",
        "description": "Returns whether selection is partial (some but not all). Renders the select-all checkbox in indeterminate state."
      },
      {
        "name": "getIsItemSelectable",
        "type": "(item: T) => boolean",
        "description": "Returns whether a row should show a checkbox. Non-selectable rows render nothing in the selection cell.",
        "default": "() => true"
      },
      {
        "name": "getIsItemEnabled",
        "type": "(item: T) => boolean",
        "description": "Returns whether a row checkbox is interactive. Disabled rows show a disabled checkbox.",
        "default": "() => true"
      },
      {
        "name": "getRowLabel",
        "type": "(item: T) => string",
        "description": "Derives a human-readable identity for a row; the row checkbox's hidden label becomes `Select ${getRowLabel(item)}` so screen readers announce which row each checkbox selects. Falls back to \"Select row\" when omitted."
      },
      {
        "name": "hasRowHighlight",
        "type": "boolean",
        "description": "Paints checked rows with the accent wash. Set false when the surrounding UI already uses row background to mean something else (a row open in a detail panel, say). The wash is an inline style, so it cannot be overridden from userland. Only the background is dropped: aria-selected is still set on checked rows either way.",
        "default": "true"
      }
    ],
    "examples": [
      {
        "label": "Accessible per-row checkbox names",
        "code": "\nconst selectionPlugin = useTableSelection({\n  getIsItemSelected: item => selectedIds.has(item.id),\n  onSelectItem: ({item, isSelected}) => toggle(item.id, isSelected),\n  onSelectAll: ({isAllSelected}) => selectAll(isAllSelected),\n  getIsAllSelected: () => selectedIds.size === users.length,\n  // Screen readers announce \"Select Alice\", \"Select Bob\", ...\n  // instead of an undifferentiated \"Select row\" for every checkbox.\n  getRowLabel: item => item.name,\n});\n\n<Table\n  data={users}\n  columns={columns}\n  idKey=\"id\"\n  plugins={{selection: selectionPlugin}}\n/>;\n"
      },
      {
        "label": "Opt out of the checked-row wash",
        "code": "\n// This table already uses row background to mean \"open in the detail\n// panel\". Turning the selection wash off keeps that meaning unambiguous;\n// the checkbox and aria-selected still carry the selection.\nconst selectionPlugin = useTableSelection({\n  getIsItemSelected: item => selectedIds.has(item.id),\n  onSelectItem: ({item, isSelected}) => toggle(item.id, isSelected),\n  onSelectAll: ({isAllSelected}) => selectAll(isAllSelected),\n  getIsAllSelected: () => selectedIds.size === users.length,\n  hasRowHighlight: false,\n});\n"
      }
    ]
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
